Check("호환되지 않는 스탠스/원본 개정/저장 형식 거부",()=>{Reject(()=>StanceCalc(stanceNaked with{WeaponId=catalog.Weapons[1].Id}));Reject(()=>StanceCalc(stanceNaked with{Stance=stanceNaked.Stance! with{Revision=1}}));Reject(()=>StanceCalc(stanceNaked with{SchemaVersion=1}));Reject(()=>Calc(stanceNaked));});
Check("슬램 콤보를 일반 타격으로 조용히 계산하지 않음",()=>Reject(()=>StanceCalc(StanceBuild(naked,"Forward Block"))));
Check("스탠스 빌드 JSON 왕복",()=>{var restored=JsonSerializer.Deserialize<Build>(JsonSerializer.Serialize(stanceNaked,Catalog.Json),Catalog.Json)!;Yes(restored.Stance==stanceNaked.Stance);Near(StanceCalc(restored).RawDps,StanceCalc(stanceNaked).RawDps);});
var noCritCatalog=catalog with{Weapons=catalog.Weapons.Select(w=>w with{CriticalChance=0}).ToArray()};
var deterministicStance=StanceEngine.Calculate(noCritCatalog,stanceNaked,stances);
Check("스탠스 TTK 첫 콤보의 시간 범위",()=>{var t=StanceEngine.Simulate(deterministicStance,1);Near(t.Median.Earliest!.Value,0);Near(t.Median.Latest!.Value,deterministicStance.Duration);});
Check("콤보 경계의 정확한 체력과 다음 콤보 구분",()=>{var c=deterministicStance;var exact=StanceEngine.Simulate(c,4653);var next=StanceEngine.Simulate(c,4654);Near(exact.Median.Earliest!.Value,0);Near(exact.Median.Latest!.Value,c.Duration);Near(next.Median.Earliest!.Value,c.Duration);Near(next.Median.Latest!.Value,2*c.Duration);});
Check("스탠스 미처치 표본과 완료된 계산 구간",()=>{var c=deterministicStance;var t=StanceEngine.Simulate(c,1e12,horizon:c.Duration!.Value*2.5);Yes(t.Median.Latest is null&&t.P90.Latest is null&&t.KillFraction==0);Near(t.Horizon,c.Duration*2);});
Check("스탠스 치명타 시드 재현성",()=>{var c=StanceCalc(stanceNaked);Yes(StanceEngine.Simulate(c,5000)==StanceEngine.Simulate(c,5000));});
Check("229개 무기와 전체 호환 동작 계산·거부 전수 검사",()=>{var supported=0;var rejected=0;foreach(var w in catalog.Weapons)foreach(var st in stances.ForWeapon(w))foreach(var cb in st.Combos){var b=stanceNaked with{WeaponId=w.Id,Stance=new(st.Id,cb.Key,stances.Revision)};if(cb.Unsupported.Length==0&&cb.Duration is >0&&cb.AttackOverride is null&&cb.Hits.All(h=>h.AttackOverride is null)&&cb.FinisherKind is null or "Ground"){var c=StanceCalc(b);Yes(c.RawDps>0&&double.IsFinite(c.RawDps!.Value));supported++;}else {Reject(()=>StanceCalc(b));rejected++;}}Yes(supported>1000&&rejected>1000);Console.WriteLine($"전수 조합: 계산 {supported}, 명시적 거부 {rejected}");});

Check("피해 0인 회복 동작은 시간에만 포함",()=>{var b=stanceNaked with{WeaponId=catalog.Weapons[2].Id,Stance=new("Cleaving Whirlwind","Forward",stances.Revision)};var c=StanceCalc(b);Yes(c.Combo.HitCount==10);Yes(c.Hits.Sum(h=>h.Count)==10);Near(c.Combo.MotionSum,15);Near(c.Duration,5.7/c.Stats.AttackSpeed);});

var capacityData=CapacityCatalog.Load();
var capDefault=capacityData.Default(naked.WeaponId,"Blind Justice");
Build WithCapacity(Build b,CapacitySetup? setup=null)=>b with{SchemaVersion=3,Capacity=setup??capDefault};
CapacityResult Capacity(Build b)=>CapacityEngine.Calculate(catalog,capacityData,b);
Check("수용량 원본: 전체 무기와 실제 스탠스/기본 동작 구분",()=>{Yes(capacityData.WeaponDefaults.Count==229);Yes(capacityData.StanceMods.Count==134);Yes(stances.Stances.Where(s=>!s.AbilityOnly&&s.ModId is not null).All(s=>capacityData.StanceMods[s.Id].Bonus==5));Yes(capacityData.StanceMods.Values.Where(m=>m.ModId.Length==0).All(m=>m.Bonus==0));});
Check("무극성 슬롯은 원래 비용",()=>Near(CapacityEngine.SlotCost(M("pressure"),5,"None"),9));
Check("일치 극성: 홀수 비용 절반 올림",()=>{Near(CapacityEngine.SlotCost(M("pressure"),5,"AP_ATTACK"),5);Near(CapacityEngine.SlotCost(M("overload"),5,"AP_ATTACK"),8);});
Check("불일치 극성: 최신 위키의 25% 증가 올림",()=>{Near(CapacityEngine.SlotCost(M("pressure"),5,"AP_DEFENSE"),12);Near(CapacityEngine.SlotCost(M("bloodrush"),10,"AP_DEFENSE"),18);});
Check("30랭크·카탈리스트·스탠스 일치: 70",()=>{var c=Capacity(WithCapacity(naked));Near(c.BaseCapacity,60);Near(c.StanceBonus,10);Near(c.Total,70);});
Check("스탠스 무극성: 보너스 5",()=>Near(Capacity(WithCapacity(naked,capDefault with{StanceSlotPolarity="None"})).Total,65));
Check("스탠스 불일치: 보너스 4",()=>Near(Capacity(WithCapacity(naked,capDefault with{StanceSlotPolarity="AP_DEFENSE"})).Total,64));
Check("스탠스 포르마: 실제 모드 보너스 10·기본 동작 0",()=>{foreach(var w in catalog.Weapons)foreach(var s in stances.ForWeapon(w)){var b=WithCapacity(naked with{WeaponId=w.Id},capacityData.Default(w.Id,s.Id) with{StanceSlotPolarity="Universal"});Near(Capacity(b).StanceBonus,capacityData.StanceMods[s.Id].ModId.Length>0?10:0);}});
Check("무기 랭크와 MR 중 큰 값 사용",()=>{var setup=capDefault with{WeaponRank=7,MasteryRank=12,Catalyst=false,StanceEquipped=false};Near(Capacity(WithCapacity(naked,setup)).Total,12);Near(Capacity(WithCapacity(naked,setup with{WeaponRank=20})).Total,20);});
Check("카탈리스트는 스탠스 보너스를 중복 배가하지 않음",()=>Near(Capacity(WithCapacity(naked,capDefault with{Catalyst=false})).Total,40));
Check("용량 초과는 음수 잔량·계획용 계산 허용",()=>{var b=WithCapacity(Build(M("pressure")),capDefault with{WeaponRank=0,MasteryRank=0,StanceEquipped=false,SlotPolarities=Enumerable.Repeat("None",8).ToArray()});var c=Capacity(b);Yes(!c.Fits);Near(c.Remaining,-9);Yes(Calc(b).ExpectedHit>0);});
Check("일반 슬롯에 스탠스 포르마 적용 차단",()=>{var p=(string[])capDefault.SlotPolarities.Clone();p[0]="Universal";Reject(()=>Capacity(WithCapacity(naked,capDefault with{SlotPolarities=p})));});
Check("수용량 설정 범위·배열 길이·호환성 검증",()=>{Reject(()=>Capacity(WithCapacity(naked,capDefault with{WeaponRank=31})));Reject(()=>Capacity(WithCapacity(naked,capDefault with{MasteryRank=-1})));Reject(()=>Capacity(WithCapacity(naked,capDefault with{SlotPolarities=[]})));Reject(()=>Capacity(WithCapacity(naked,capDefault with{StanceId="Sovereign Outcast"})));});
Check("스탠스 미장착 빌드에 콤보 계산 차단",()=>Reject(()=>StanceCalc(WithCapacity(stanceNaked,capDefault with{StanceEquipped=false}))));
Check("버전 3 누락 수용량 설정 차단",()=>{Reject(()=>Calc(naked with{SchemaVersion=3}));Reject(()=>StanceCalc(stanceNaked with{SchemaVersion=3}));});
Check("해제한 스탠스도 저장 식별자 유효성 검증",()=>Reject(()=>Calc(WithCapacity(naked,capDefault with{StanceEquipped=false,StanceId="없는 스탠스"}))));
Check("이전 저장 형식에 수용량을 혼합하지 않음",()=>{Reject(()=>Calc(naked with{Capacity=capDefault}));Reject(()=>StanceCalc(stanceNaked with{Capacity=capDefault}));});
Check("버전 3 JSON 극성·카탈리스트·랭크 왕복",()=>{var b=WithCapacity(stanceNaked,capDefault with{WeaponRank=12,MasteryRank=20,Catalyst=false,StanceSlotPolarity="Universal"});var restored=JsonSerializer.Deserialize<Build>(JsonSerializer.Serialize(b,Catalog.Json),Catalog.Json)!;Yes(restored.Capacity!.SlotPolarities.SequenceEqual(b.Capacity!.SlotPolarities));Yes(!restored.Capacity.Catalyst);Near(Capacity(restored).Total,30);Near(StanceCalc(restored).RawDps,StanceCalc(stanceNaked).RawDps);});

