var example = Build(M("pressure"),M("bloodrush"),M("shatter"),M("fury"),M("virulent"),M("vicious"),M("weeping"),M("overload")) with {Scenario=new(Combo:12,Enemy:new(10000,2700))};
var watch=Stopwatch.StartNew(); for(var i=0;i<10000;i++)Calc(example);watch.Stop();var calcMicroseconds=watch.Elapsed.TotalMicroseconds/10000;
var c0=Calc(example);DamageEngine.Simulate(c0,10000);var samples=new List<double>();
for(int i=0;i<20;i++){watch.Restart();DamageEngine.Simulate(c0,10000);watch.Stop();samples.Add(watch.Elapsed.TotalMilliseconds);}samples.Sort();
var stancePerf=StanceCalc(StanceBuild(example));watch.Restart();for(var i=0;i<20;i++)StanceEngine.Simulate(stancePerf,10000);watch.Stop();var stanceSimulationMean=watch.Elapsed.TotalMilliseconds/20;
var modernCatalog=Catalog.LoadMelee();var modernBuild=example with {SchemaVersion=5,Capacity=CapacityCatalog.Load().Default(example.WeaponId,null) with {StanceEquipped=false},Melee=new(Faction:"Grineer",Statuses:new(){[DamageType.Viral]=10,[DamageType.Corrosive]=10})};
for(var i=0;i<100;i++)DamageEngine.Calculate(modernCatalog,modernBuild);
var bytes=GC.GetAllocatedBytesForCurrentThread();watch.Restart();for(var i=0;i<5000;i++)DamageEngine.Calculate(modernCatalog,modernBuild);watch.Stop();var modernMean=watch.Elapsed.TotalMicroseconds/5000;var modernBytes=(GC.GetAllocatedBytesForCurrentThread()-bytes)/5000;
var modernCalc=DamageEngine.Calculate(modernCatalog,modernBuild);var modernSamples=new List<double>();
for(var i=0;i<10;i++){watch.Restart();DamageEngine.Simulate(modernCalc,10000);watch.Stop();modernSamples.Add(watch.Elapsed.TotalMilliseconds);}modernSamples.Sort();
var modernStanceSlots=(ModSlot?[])modernBuild.Slots.Clone();modernStanceSlots[7]=null;
var modernStance=StanceEngine.Calculate(modernCatalog,modernBuild with {Slots=modernStanceSlots,Stance=new("Blind Justice","Neutral",stances.Revision),Capacity=CapacityCatalog.Load().Default(example.WeaponId,"Blind Justice")},stances);watch.Restart();for(var i=0;i<5;i++)StanceEngine.Simulate(modernStance,10000);watch.Stop();var modernStanceMean=watch.Elapsed.TotalMilliseconds/5;
var encounterBench=modernBuild with {Scenario=modernBuild.Scenario with {Combo=1},Stance=new("Blind Justice","Neutral",stances.Revision),Capacity=CapacityCatalog.Load().Default(example.WeaponId,"Blind Justice"),Encounter=new(EncounterMode.TenSeconds)};
var encounterTimes=new List<double>();for(var i=0;i<5;i++){watch.Restart();var encounterRun=EncounterEngine.Calculate(modernCatalog,encounterBench,stances,128);watch.Stop();if(encounterRun.Unsupported.Length>0)throw new Exception(string.Join(" · ",encounterRun.Unsupported));encounterTimes.Add(watch.Elapsed.TotalMilliseconds);}
encounterTimes.Sort();
var report=new {encounterPerformance=new{rules=EncounterEngine.Version,trials=128,horizon=10,medianMilliseconds=encounterTimes[2],maximumMilliseconds=encounterTimes[^1],note="Nikana Prime · Blind Justice 정지 · CO 포함 8모드 · 시작 콤보1. 단일 프로세스 측정, 게임 병행 아님."},stanceRules=StanceEngine.RulesVersion,stanceSimulationMeanMilliseconds=stanceSimulationMean,passed=names.Count,failed,tests=names,performance=new{calculationMeanMicroseconds=calcMicroseconds,simulationP50Milliseconds=samples[9],simulationP95Milliseconds=samples[18],trials=2048,note="이전 계산 경로의 회귀 측정. 확장 근접 경로는 modernPerformance 참조."},modernPerformance=new{rules=MeleeEngine.RulesVersion,calculationMeanMicroseconds=modernMean,calculationAllocatedBytes=modernBytes,simulationP50Milliseconds=modernSamples[4],simulationMaximumMilliseconds=modernSamples[^1],stanceSimulationMeanMilliseconds=modernStanceMean,trials=2048,note="단일 공격 8모드, 스탠스 TTK는 CO 제외 7모드·12콤보·바이러스/부식 10중첩·그리니어 대상. Release 단일 프로세스 참고값. 실제 게임 병행·GPU 부하·입력 지연 측정 아님."},rules=DamageEngine.RulesVersion,data=catalog.Version,date="2026-10-11"};
if(args.Length>0)File.WriteAllText(args[0],JsonSerializer.Serialize(report,Catalog.Json));
Console.WriteLine($"\n검증 {names.Count}개 통과, {failed.Count}개 실패. 평균 계산 {calcMicroseconds:F1} µs, 시뮬레이션 P95 {samples[18]:F2} ms.");
Environment.ExitCode=failed.Count==0?0:1;
